c_{k^{\prime},l^{\prime},m^{\prime}}e^{2\pi im^{\prime}\lambda}.

theorem.raw:
\label{3pth4}
For every measurable subset $A\subset\mathbb{T}^{n}$ with $\lambda{(A)}> 0$, $\lambda{(A^{c})}> 0$, there exists non-zero $f\in L^{2}(\mathbb{T}^{n})$ such that
\begin{enumerate}
\item supp~$f\subset A$;
\item there exists $M> 0$ such that $\|S_{n}(f)\|_{L^{\infty}(\mathbb{T}^{n})}\leq M$ for all $n\in\mathbb{N}$, where $S_{n}(f)$ denotes the nth partial sum of the Fourier series of $f$.
\end{enumerate}

\label{3pth8}
Let $\varphi\in L^{2}(\mathbb{R}^{2n})$ be such that $\varphi$ satisfies condition C and $\frac{1}{w_{\varphi}}\in L^{1}(\mathbb{T}^{n})$. Then the following are equivalent.
\begin{enumerate}
\item [(a)] $\{T_{(k,l)}^{t}\varphi:(k,l)\in\mathbb{Z}^{2n}\}$ is Hilbertian.
\item [(b)] $\|w_{\varphi}\|_{\infty}<\infty$.
\item [(c)] $\{T_{(k,l)}^{t}\varphi:(k,l)\in\mathbb{Z}^{2n}\}$ is a Bessel sequence.
\end{enumerate}

\label{3pth9}
Let $\varphi\in L^{2}(\mathbb{R}^{2n})$ be such that $\varphi$ satisfies condition C and $\frac{1}{w_{\varphi}}\in L^{1}(\mathbb{T}^{n})$. If any one of the equivalent conditions of Theorem \ref{3pth8} is true, then there exists $\tilde{\varphi}\in V^{t}(\varphi)$, canonical dual to $\varphi$ such that $\{T_{(k,l)}^{t}\tilde{\varphi}:(k,l)\in\mathbb{Z}^{2n}\}$ is Besselian.

Moreover, if $\{T_{(k,l)}^{t}\varphi:(k,l)\in\mathbb{Z}^{2n}\}$ is Besselian and if for each $\psi\in V^{t}(\varphi)$ there exists a sequence $\{c_{k,l}\}$ such that $\psi=\sum\limits_{k,l\in\mathbb{Z}^{n}}c_{k,l}T_{(k,l)}^{t}\varphi$, then $\|\frac{1}{w_{\varphi}}\|_{\infty}<\infty$.

\label{3pth12}
Let $\varphi\in L^{2}(\mathbb{H}^{n})$ be such that $\varphi$ satisfies condition C. Then there exists a canonical dual $\tilde{\varphi}$ to $\varphi$ that belongs to $V(\varphi)$ if and only if $\frac{1}{G_{0,0}^{\varphi}}\in L^{1}(0,1]$. Moreover, in this case, $\widehat{\tilde{\varphi}}(\lambda)=\frac{1}{G_{0,0}^{\varphi}(\lambda)}
\widehat{\varphi}(\lambda)$.

Let $\varphi\in L^{2}(\mathbb{H}^{n})$ be such that $\varphi$ satisfies condition C and $\frac{1}{G_{0,0}^{\varphi}}\in L^{1}(0,1]$. Then the following are equivalent.
\begin{enumerate}
\item [(a)] $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ is Hilbertian.
\item [(b)] $\|G_{0,0}^{\varphi}\|_{\infty}<\infty$.
\item [(c)] $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ is a Bessel sequence.
\end{enumerate}

lemma.raw:
Let $\varphi \in L^{2}(\mathbb {R}^{2n})$. Then the kernel of the Weyl transform of $T_{(k,l)}^{t}\varphi$ satisfies the following relation.
\begin{eqnarray}\label{3peq1}
K_{T_{(k,l)}^{t}\varphi}(\xi,\eta)=e^{\pi i (2\xi+l).k}K_{\varphi}(\xi+l,\eta).
\end{eqnarray}

Let $\{c_{k,l}:(k,l)\in\mathbb{Z}^{2n}\}$ be a finite sequence and $\varphi\in L^{2}(\mathbb{R}^{2n})$ be such that $\varphi$ satisfies condition C. Then
\begin{eqnarray}
\bigg\|\sum\limits_{(k,l)\in\mathcal{F}}c_{k,l}T_{(k,l)}^{t}\varphi\bigg\|_{L^{2}(\mathbb{R}^{2n})}^{2}=\sum\limits_{l}
\int\limits_{\mathbb {T}^{n}}\bigg|\sum\limits_{k}c_{k,l}e^{\pi il.k}e^{2\pi ik.\xi}\bigg|^{2} w_{\varphi}(\xi)d\xi,\label{3peq6}
\end{eqnarray}
where $\mathcal{F}$ denotes a finite set.

remark.raw:
In order to show that a function $\varphi\in L^{2}(\mathbb{H}^{n})$ satisfies condition C, it is enough to show that all the Fourier coefficients of $G_{k,l}^{\varphi}$ vanish when $(k,l)\in\mathbb{Z}^{2n}\setminus \{(0,0)\}$.
But
\begin{eqnarray}
\widehat{G_{k,l}^{\varphi}}(m)=\int\limits_{0}^{1} G_{k,l}^{\varphi}(\lambda) e^{-2\pi im\lambda}d\lambda
=\langle\varphi, L_{(2k,l,m)}\varphi\rangle_{L^{2}(\mathbb{H}^{n})}.\label{3pr6}
\end{eqnarray}
Thus it is enough to show that $\langle\varphi, L_{(2k,l,m)}\varphi\rangle=0,~\forall~m\in\mathbb{Z}$, whenever $(k,l)\neq (0,0)$.

Let $m=0$ in \eqref{3pr6}. Then we have
\begin{eqnarray*}
\int\limits_{0}^{1}G_{k,l}^{\varphi}(\lambda)d\lambda=\langle\varphi, L_{(2k,l,0)}\varphi\rangle<\infty,
\end{eqnarray*}
which shows that the function $G_{k,l}^{\varphi}(\lambda)$, defined in \eqref{3peq18}, is finite a.e. $\lambda\in (0,1]$.

