\begin{example}
We shall first provide some examples of functions in $L^{2}(\mathbb{H})$ which satisfy condition C.
\end{example}
\begin{itemize}
\item [1.] Let $\varphi(x,y,t)=\chi_{[0,2]}(x)\chi_{[0,1]}(y)h(t)$, where $h$ is an arbitrary function in $L^{2}(\mathbb{R})$. Then
\begin{eqnarray*}
L_{(2k,l,m)}\varphi (x,y,t)
&=&\varphi(x-2k,y-l,t-m+\frac{1}{2}(2ky-xl))\\
&=& \chi_{[0,2]}(x-2k)\chi_{[0,1]}(y-l) h(t-m+ky-\frac{l}{2}x)\\
&=& \chi_{[2k,2k+2]}(x)\chi_{[l,l+1]}(y) h(t-m+ky-\frac{l}{2}x).
\end{eqnarray*}
Since for $(k,l)\neq (0,0), [0,2]\times [0,1]~\bigcap~ [2k,2k+2]\times [l,l+1]=\emptyset,$  it follows that $\langle \varphi, L_{(2k,l,m)}\varphi\rangle=0,~\forall~ m\in\mathbb{Z}$. Then from \eqref{3pr6}, we get $\widehat{G_{k,l}^{\varphi}}(m)=0,~\forall~ m\in\mathbb{Z}$ whenever $(k,l)\neq (0,0)$. Thus $\varphi$ satisfies condition C.

Hence $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ does not form an orthonormal system in $L^{2}(\mathbb{H})$.
\item [3.] Instead of $e^{-t^{2}}$, one can take $e^{-|t|}$ or in general any $h\in L^{2}(\mathbb{R})$ for which $\int\limits_{\mathbb{R}}h(t)h(t-1)dt\neq 0$. Then $\langle\varphi, L_{(0,0,1)}\varphi\rangle\neq 0$.
\item [4.] Let $\varphi(x,y,t)=f(x)g(y)h(t)$, where $supp~f\bigcap supp~\tau_{2k}f=\emptyset,~\forall~k\neq 0$ and $supp~g\bigcap supp~\tau_{l}g=\emptyset,~\forall~l\neq 0,~h\in L^{2}(\mathbb{R})$. Then the same proof discussed in Example 1 can be used to show that $\varphi$ satisfies condition C. Again as an example, we can take
