L_{(2k,l,m)}\varphi (x,y,t)
&=&\varphi(x-2k,y-l,t-m+\frac{1}{2}(2ky-xl))\\
&=& \chi_{[0,2]}(x-2k)\chi_{[0,1]}(y-l) h(t-m+ky-\frac{l}{2}x)\\
&=& \chi_{[2k,2k+2]}(x)\chi_{[l,l+1]}(y) h(t-m+ky-\frac{l}{2}x).
\end{eqnarray*}
Since for $(k,l)\neq (0,0), [0,2]\times [0,1]~\bigcap~ [2k,2k+2]\times [l,l+1]=\emptyset,$  it follows that $\langle \varphi, L_{(2k,l,m)}\varphi\rangle=0,~\forall~ m\in\mathbb{Z}$. Then from \eqref{3pr6}, we get $\widehat{G_{k,l}^{\varphi}}(m)=0,~\forall~ m\in\mathbb{Z}$ whenever $(k,l)\neq (0,0)$. Thus $\varphi$ satisfies condition C.

In \cite{ra}, we have proved the theorem that $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ is an orthonormal system in $L^{2}(\mathbb{H}^{n})$ if and only if $G_{0,0}^{\varphi}(\lambda)=1$ a.e. $\lambda\in (0,1]$ and $\varphi$ satisfies condition C. Thus it is meaningful to give an example of a function $\varphi$ which satisfies condition C but $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ is not an orthonormal system. This is illustrated in Example 2 and Example 3.
\item [2.] We take $h(t)=e^{-t^{2}}, t\in\mathbb{R},$ in Example 1. For this function $h$, the correspond-ing $\varphi$ satisfies $\langle\varphi, L_{(0,0,1)}\varphi\rangle\neq 0$.
Hence $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$ does not form an orthonormal system in $L^{2}(\mathbb{H})$.
\item [3.] Instead of $e^{-t^{2}}$, one can take $e^{-|t|}$ or in general any $h\in L^{2}(\mathbb{R})$ for which $\int\limits_{\mathbb{R}}h(t)h(t-1)dt\neq 0$. Then $\langle\varphi, L_{(0,0,1)}\varphi\rangle\neq 0$.
\item [4.] Let $\varphi(x,y,t)=f(x)g(y)h(t)$, where $supp~f\bigcap supp~\tau_{2k}f=\emptyset,~\forall~k\neq 0$ and $supp~g\bigcap supp~\tau_{l}g=\emptyset,~\forall~l\neq 0,~h\in L^{2}(\mathbb{R})$. Then the same proof discussed in Example 1 can be used to show that $\varphi$ satisfies condition C. Again as an example, we can take
\begin{eqnarray*}
f(x)&=\left\{
\begin{array}{l l}
e^{-\frac{1}{x(2-x)}},& \quad \text{$0<x<2$,}\\
0, & \quad \text{otherwise,}
\end{array}\right.
\end{eqnarray*}
and
\begin{eqnarray*}
g(x)&=\left\{
\begin{array}{l l}
e^{-\frac{1}{x(1-x)}},& \quad \text{$0<x<1$,}\\
0, & \quad \text{otherwise,}
\end{array}\right.
\end{eqnarray*}
and $h(t)=e^{-t^{2}},~t\in\mathbb{R}$.

Now we shall provide examples of functions in $L^{2}(\mathbb{H})$, which do not satisfy condition C.
\item [5.]Let $\varphi(x,y,t)=\chi_{[0,3]}(x)\chi_{[0,1]}(y)h(t)$, where $h$ is an arbitrary function in $L^{2}(\mathbb{R})$. Then it can be shown that 
\begin{eqnarray*}
\langle\varphi, L_{(2,0,0)}\varphi\rangle
=\int\limits_{0}^{1}\int\limits_{\mathbb{R}} h(t)\overline{h(t+y)}dtdy.
\end{eqnarray*}
Choose $h$ in such a way that the above integral is non-zero. For example, we can take $h(t)=sinct,~t\in\mathbb{R}$. Then
\begin{eqnarray*}
\langle\varphi, L_{(2,0,0)}\varphi\rangle
=\int\limits_{0}^{1}\frac{sin\pi y}{\pi y}dy
>0.
\end{eqnarray*}
Thus from \eqref{3pr6}, we have $\widehat{G_{1,0}^{\varphi}}(0)\neq 0$, showing that $\varphi$ does not satisfy condition C. 

\item [6.] More generally, let $\varphi(x,y,t)=f(x)g(y)h(t)$, where the value of both the integrals $\int\limits_{\mathbb{R}} f(x)\overline{f(x-2)}dx$ and $\int\limits_{\mathbb{R}}\int\limits_{\mathbb{R}}|g(y)|^{2}h(t)\overline{h(t+y)}dt dy$ are non-zero. Since
$\langle\varphi, L_{(2,0,0)}\varphi\rangle\neq 0$, $\varphi$ does not satisfy condition C. For example, we can take $f(x)=e^{-|x|},~x\in\mathbb{R},~ h(t)=sinct,~t\in\mathbb{R}$ and 
\begin{eqnarray*}
g(y)&=\left\{
\begin{array}{l l}
\frac{1}{n+1},& \quad \text{$y\in [2n,2n+1],~n=0,1,2,\dotsc $,}\\
0, & \quad \text{otherwise.}
\end{array}\right.
\end{eqnarray*}
 \end{itemize}
\begin{rem}
Let $m=0$ in \eqref{3pr6}. Then we have
\begin{eqnarray*}
\int\limits_{0}^{1}G_{k,l}^{\varphi}(\lambda)d\lambda=\langle\varphi, L_{(2k,l,0)}\varphi\rangle<\infty,
\end{eqnarray*}
which shows that the function $G_{k,l}^{\varphi}(\lambda)$, defined in \eqref{3peq18}, is finite a.e. $\lambda\in (0,1]$.
\end{rem}

The following theorem is a consequence of Theorem 4.1 in \cite{ra}. For its proof, we refer to \cite{ra}.

Let $\varphi\in L^{2}(\mathbb{H}^{n})$ be such that $\varphi$ satisfies condition C. Suppose $A(\varphi)=$ span $\{L_{(2k,l,m)}\varphi:(k,l,m)\in\mathbb{Z}^{2n+1}\}$. Then  $V(\varphi)=\overline{A(\varphi)}$. Let $f\in A(\varphi)$ i.e., $f=\sum\limits_{(k^{\prime},l^{\prime},m^{\prime})\in\mathcal{F}}
c_{k^{\prime},l^{\prime},m^{\prime}}L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi$, where $\mathcal{F}$ is a finite set. Define $\rho(\lambda)=\fontdimen16\textfont2=5pt \{\rho_{k^{\prime},l^{\prime}}(\lambda)\}_
{(k^{\prime},l^{\prime})}$ for $\lambda\in (0,1]$, where
\begin{eqnarray}\label{3pr1}
\fontdimen16\textfont2=5pt \rho_{k^{\prime},l^{\prime}}(\lambda)=\sum\limits_{m^{\prime}}
c_{k^{\prime},l^{\prime},m^{\prime}}e^{2\pi im^{\prime}\lambda}.
\end{eqnarray}
Define $J_{\varphi}(f)=\rho$.

(The above result has been proved for a more general case in \cite{ra}. However, for the sake of completeness, we provide the proof here.)
\begin{pf}
Let $f\in A(\varphi)$. Then
\begin{eqnarray}
\widehat{f}(\lambda)&=&\sum\limits_{(k^{\prime},l^{\prime},m^{\prime})\in\mathcal{F}}
c_{k^{\prime},l^{\prime},m^{\prime}}\widehat {L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi}(\lambda)\nonumber\\
&=&\sum\limits_{k^{\prime},l^{\prime},m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\widehat {L_{(2k^{\prime},l^{\prime},0)}\varphi}(\lambda)\nonumber\\
&=&\sum\limits_{k^{\prime},l^{\prime}}\fontdimen16\textfont2=5pt \rho_{k^{\prime},l^{\prime}}(\lambda)\widehat {L_{(2k^{\prime},l^{\prime},0)}\varphi}(\lambda),\label{3pr5}
\end{eqnarray}
using \eqref{3pr1} and $\rho(\lambda)=\fontdimen16\textfont2=5pt \{\rho_{k^{\prime},l^{\prime}}(\lambda)\}_
{(k^{\prime},l^{\prime})}$.

Conversely let $\rho(\lambda)=\fontdimen16\textfont2=5pt \{\rho_{k^{\prime},l^{\prime}}(\lambda)\}_
{(k^{\prime},l^{\prime})\in\mathcal{F}}$, where $\rho_{k^{\prime},l^{\prime}}(\lambda)$ is given by \eqref{3pr1}. Define $f=\sum\limits_{(k^{\prime},l^{\prime},m^{\prime})\in\mathcal{F}}
c_{k^{\prime},l^{\prime},m^{\prime}}L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi$. Then $f\in A(\varphi)$. Thus we see that there is a one to one correspondence between $A(\varphi)$ and the collection of functions of the form $\rho$. Further, we have
\begin{eqnarray}
\|f\|^{2}&=&\bigg\|\sum\limits_{(k^{\prime},l^{\prime},m^{\prime})\in\mathcal{F}}
c_{k^{\prime},l^{\prime},m^{\prime}}L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi\bigg\|^{2}\nonumber\\
&=&\sum\limits_{k^{\prime},l^{\prime}}\int\limits_{0}^{1}\bigg|\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}}e^{2\pi im^{\prime}\lambda}\bigg|^{2}G_{0,0}^{\varphi}(\lambda)d\lambda.\label{3peq14}
\end{eqnarray}
In fact,
\begin{eqnarray}
&&\bigg\|\sum\limits_{(k^{\prime},l^{\prime},m^{\prime})\in\mathcal{F}} c_{k^{\prime},l^{\prime},m^{\prime}}L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi\bigg\|_{L^{2}(\mathbb{H}^{n})}^{2}\nonumber\\
&=&\int\limits_{\mathbb{R}}\bigg\|\sum\limits_{k^{\prime},l^{\prime},m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}}
\widehat{L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi(\lambda)}\bigg\|_{\mathcal{B}_{2}}^{2}
|\lambda|^{n}d\lambda\nonumber\\
&=&\int\limits_{0}^{1}\sum\limits_{r\in\mathbb{Z}}\bigg\|\sum\limits_{k^{\prime},l^{\prime},m^{\prime}}
c_{k^{\prime},l^{\prime},m^{\prime}}\widehat{L_{(2k^{\prime},l^{\prime},m^{\prime})}\varphi}(\lambda+r)\bigg\|
_{\mathcal{B}_{2}}^{2}|\lambda+r|^{n}d\lambda\nonumber\\
&=&\int\limits_{0}^{1}\sum\limits_{r\in\mathbb{Z}}\bigg\|\sum\limits_{k^{\prime},l^{\prime}}
\bigg(\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\bigg)\widehat{L_{(2k^{\prime},l^{\prime},0)}\varphi}(\lambda+r)\bigg\|
_{\mathcal{B}_{2}}^{2}|\lambda+r|^{n}d\lambda\nonumber
\end{eqnarray}
\begin{eqnarray}
&=&\int\limits_{0}^{1}\sum\limits_{r\in\mathbb{Z}}\sum\limits_{k^{\prime},l^{\prime}}\bigg\|
\bigg(\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\bigg)\widehat{L_{(2k^{\prime},l^{\prime},0)}\varphi}(\lambda+r)\bigg\|
_{\mathcal{B}_{2}}^{2}|\lambda+r|^{n}d\lambda\nonumber\\
&+&\int\limits_{0}^{1}\sum\limits_{r\in\mathbb{Z}}
\sum\limits_{(k_{1}^{\prime},l_{1}^{\prime})\neq (k_{2}^{\prime},l_{2}^{\prime})}\bigg\langle\bigg(\sum\limits_{m^{\prime}}c_{k_{1}^{\prime},l_{1}^{\prime},m^{\prime}}e^{2\pi i m^{\prime}\lambda}\bigg)\widehat{L_{(2k_{1}^{\prime},l_{1}^{\prime},0)}\varphi}(\lambda+r),\nonumber\\
&&\bigg(\sum\limits_{m^{\prime}}c_{k_{2}^{\prime},l_{2}^{\prime},m^{\prime}}e^{2\pi i m^{\prime}\lambda}\bigg)\widehat{L_{(2k_{2}^{\prime},l_{2}^{\prime},0)}\varphi}(\lambda+r)\bigg\rangle
_{\mathcal{B}_{2}}|\lambda+r|^{n}d\lambda,\label{2peq13}
\end{eqnarray}
using \eqref{3peq20}. Now, using \eqref{3peq18} and the fact that $\|\widehat{L_{(2k,l,0)}\varphi}(\lambda)\|_{\mathcal{B}_{2}}=\|\widehat{\varphi}(\lambda)\|_{\mathcal{B}_{2}},~\forall~ k,l\in\mathbb{Z}^{n}$, the first term on the right hand side of \eqref{2peq13} becomes
\begin{eqnarray}
&&\int\limits_{0}^{1}\sum\limits_{r\in\mathbb{Z}}\sum\limits_{k^{\prime},l^{\prime}}
\bigg|\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\bigg|^{2}\|\widehat{L_{(2k^{\prime},l^{\prime},0)}\varphi}(\lambda+r)\|
_{\mathcal{B}_{2}}^{2}|\lambda+r|^{n}d\lambda\nonumber\\
&=&\int\limits_{0}^{1}\sum\limits_{k^{\prime},l^{\prime}}
\bigg|\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\bigg|^{2}\sum\limits_{r\in\mathbb{Z}}\|\widehat{\varphi}
(\lambda+r)\|_{\mathcal{B}_{2}}^{2}|\lambda+r|^{n}d\lambda\nonumber\\
&=&\int\limits_{0}^{1}\sum\limits_{k^{\prime},l^{\prime}}
\bigg|\sum\limits_{m^{\prime}}c_{k^{\prime},l^{\prime},m^{\prime}} e^{2\pi im^{\prime}\lambda}\bigg|^{2}G_{0,0}^{\varphi}(\lambda)d\lambda.\label{2peq15}
\end{eqnarray}
The second term on the right hand side of \eqref{2peq13} is
\begin{eqnarray*}
&&\int\limits_{0}^{1}
\sum\limits_{(k_{1}^{\prime},l_{1}^{\prime})\neq (k_{2}^{\prime},l_{2}^{\prime})}\sum\limits_{m_{1}^{\prime},m_{2}^{\prime}}
c_{k_{1}^{\prime},l_{1}^{\prime},m_{1}^{\prime}}\overline{c_{k_{2}^{\prime},l_{2}^{\prime},m_{2}^{\prime}}}e^{2\pi i(m_{1}^{\prime}-m_{2}^{\prime})\lambda}\\
&&\times\sum\limits_{r\in\mathbb{Z}}\langle\widehat{L_{(2k_{1}^{\prime},l_{1}^{\prime},0)}\varphi}(\lambda+r),
\widehat{L_{(2k_{2}^{\prime},l_{2}^{\prime},0)}\varphi}(\lambda+r)\rangle
_{\mathcal{B}_{2}}|\lambda+r|^{n}d\lambda=0,
\end{eqnarray*}
as $\varphi$ satisfies condition C. Thus \eqref{3peq14} follows from \eqref{2peq13} and \eqref{2peq15}. Then, using \eqref{3pr1}, we have
\begin{eqnarray*}
\|f\|^{2}=\sum\limits_{k^{\prime},l^{\prime}}\int\limits_{0}^{1} |\rho_{k^{\prime},l^{\prime}}(\lambda)|^{2} G_{0,0}^{\varphi}(\lambda) d\lambda
&=&\int\limits_{0}^{1} \|\rho(\lambda)\|_{\ell^{2}(\mathbb{Z}^{2n})}^{2}G_{0,0}^{\varphi}(\lambda) d\lambda\\
&=&\|\rho\|_{L^{2}((0,1],\ell^{2}(\mathbb{Z}^{2n}),G_{0,0}^{\varphi})}^{2}.
\end{eqnarray*}
Hence $J(\varphi)$ is an isometry. Using density argument this isometry can be extended to the whole of $V(\varphi)$. Moreover from \eqref{3pr5}, we have $f\in V(\varphi)$ if and only if
\begin{eqnarray}\label{3peq13}
\widehat{f}(\lambda)=\sum\limits_{k^{\prime},l^{\prime}\in\mathbb{Z}^{n}}
\fontdimen16\textfont2=5pt \rho_{k^{\prime},l^{\prime}}(\lambda)\widehat{L_{(2k^{\prime},l^{\prime},
0)}\varphi}(\lambda),
\end{eqnarray}
where $\rho(\lambda)=\{\fontdimen16\textfont2=5pt \rho_{k^{\prime},l^{\prime}}(\lambda)\}_
{(k^{\prime},l^{\prime})\in\mathbb{Z}^{2n}}$ and $\rho\in L^{2}((0,1],\ell^{2}(\mathbb{Z}^{2n}),G_{0,0}^{\varphi})$.
\end{pf}

The following definitions and results are in accordance with \cite{hre}.
\begin{defn}\label{3pdef6}
An element $\varphi\in\mathcal{H}$ is said to be a canonical dual to the system $\{f_{k}:k\in\mathbb{Z}\}$ if $\langle f_{k},\varphi\rangle=\delta_{k,0},~\forall~k\in\mathbb{Z}$. In case, if $f_{k}$ is generated from a single function $f$ by some transformation, then $\varphi$ is called a canonical dual to $f$.
\end{defn}
\begin{defn}
A sequence $\{f_{k}:{k \in\mathbb {Z}}\}$ in $\mathcal{H}$ is said to be Besselian if $\sum\limits_{k\in\mathbb{Z}}c_{k}f_{k}$ is convergent implies $\{c_{k}\}\in\ell^{2}(\mathbb{Z})$.
\end{defn}
\begin{defn}
A sequence $\{f_{k}:{k \in\mathbb {Z}}\}$ in $\mathcal{H}$ is said to be Hilbertian if $\{c_{k}\}\in\ell^{2}(\mathbb{Z})$ implies $\sum\limits_{k\in\mathbb{Z}}c_{k}f_{k}$ converges.
\end{defn}

items.raw:
In order to show that a function $\varphi\in L^{2}(\mathbb{H}^{n})$ satisfies condition C, it is enough to show that all the Fourier coefficients of $G_{k,l}^{\varphi}$ vanish when $(k,l)\in\mathbb{Z}^{2n}\setminus \{(0,0)\}$.
But
\begin{eqnarray}
\widehat{G_{k,l}^{\varphi}}(m)=\int\limits_{0}^{1} G_{k,l}^{\varphi}(\lambda) e^{-2\pi im\lambda}d\lambda
=\langle\varphi, L_{(2k,l,m)}\varphi\rangle_{L^{2}(\mathbb{H}^{n})}.\label{3pr6}
\end{eqnarray}
Thus it is enough to show that $\langle\varphi, L_{(2k,l,m)}\varphi\rangle=0,~\forall~m\in\mathbb{Z}$, whenever $(k,l)\neq (0,0)$.

Let $m=0$ in \eqref{3pr6}. Then we have
\begin{eqnarray*}
\int\limits_{0}^{1}G_{k,l}^{\varphi}(\lambda)d\lambda=\langle\varphi, L_{(2k,l,0)}\varphi\rangle<\infty,
\end{eqnarray*}
which shows that the function $G_{k,l}^{\varphi}(\lambda)$, defined in \eqref{3peq18}, is finite a.e. $\lambda\in (0,1]$.

